            if (dfs(v)) return true;
        } else if (onStack[v]) {
            inCycle[v] = true;
            return true;
        }
    }
    onStack[u] = false;
    return false;
}

for (let i = 1; i <= n; i++) {
    if (!visited[i]) {
        dfs(i);
    }
}

const result = [];
for (let i = 1; i <= n; i++) {
    if (f[i - 1] === 1 || f[i - 1] === 2) {
        result.push(1);
    } else {
        result.push(inCycle[i] ? 1 : 0);
    }
}

console.log(result.join('\n'));
